#!/usr/bin/env bash
# Assemble a kernel collection from the built XNU kernel.
#
# Usage:
#   ./scripts/build-fileset.sh [--kext KEXT.kext ...] [--codeless KEXT.kext ...]
#                              [--with-kpi]
#
# Real Apple kexts (AppleACPIPlatformExpert, IOACPIFamily, storage, HID, ...)
# are passed with --kext.  --with-kpi adds the KPI pseudo-kexts generated by
# the XNU build (config/System.kext/PlugIns) as codeless entries: real kexts
# declare OSBundleLibraries on them, and OSKext resolves those dependencies
# from _PrelinkInfoDictionary.  Their CFBundleVersion is rewritten to 1.0
# because the build version (12377.121.6) is rejected by OSKext.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=env.sh
source "${SCRIPT_DIR}/env.sh"

KERNEL="${CROSSXNU_XNU}/BUILD/obj/RELEASE_X86_64/kernel"
KCB="${CROSSXNU_BUILD}/kc-tools/bin/kc-builder"
OUT="${CROSSXNU_BUILD}/kernel.kc"
KPI_DIR="${CROSSXNU_XNU}/BUILD/obj/RELEASE_X86_64/config/System.kext/PlugIns"

usage() {
    sed -n '2,9p' "${BASH_SOURCE[0]}" | sed 's/^# \{0,1\}//'
}

kexts=()
codeless=()
with_kpi=""
while [[ $# -gt 0 ]]; do
    case "$1" in
        --kext)     kexts+=("$2"); shift 2 ;;
        --codeless) codeless+=("$2"); shift 2 ;;
        --with-kpi) with_kpi=1; shift ;;
        -h|--help)  usage; exit 0 ;;
        *) echo "error: unknown argument: $1" >&2; exit 1 ;;
    esac
done

[[ -x "${KCB}" ]] || { echo "error: kc-builder missing; run ./scripts/build-kc-tools.sh" >&2; exit 1; }
[[ -f "${KERNEL}" ]] || { echo "error: kernel not built" >&2; exit 1; }

# KPI pseudo-kexts describe the kernel's own symbol sets
# (com.apple.kpi.*, com.apple.iokit.ApplePlatformFamily, ...).  They have no
# executable code, but real Apple kexts declare OSBundleLibraries on them, so
# they appear in _PrelinkInfoDictionary when --with-kpi is used.  OSKext
# rejects the raw build version (12377.121.6), so the copies get 1.0.
if [[ -n "${with_kpi}" && -d "${KPI_DIR}" ]]; then
    kpi_out="${CROSSXNU_BUILD}/kpi-codeless"
    rm -rf "${kpi_out}"
    mkdir -p "${kpi_out}"
    for k in "${KPI_DIR}"/*.kext; do
        [[ -d "${k}" ]] || continue
        dst="${kpi_out}/$(basename "${k}")"
        cp -a "${k}" "${dst}"
        sed -i -E 's|<string>[0-9]{4,}\.[0-9]+\.[0-9]+</string>|<string>9999.0.0</string>|g' \
            "${dst}/Info.plist"
        codeless+=("${dst}")
    done
fi

args=(-kernel "${KERNEL}")
for k in "${kexts[@]}"; do
    args+=(-kext "${k}")
done
for k in "${codeless[@]}"; do
    args+=(-codeless "${k}")
done
"${KCB}" "${args[@]}" -o "${OUT}"

file "${OUT}"
echo "kernel collection: ${OUT}"
